import java.util.*;
import java.io.*;

public class Main {
    static int n, k;
    static long mod;
    static int[] factorials = new int[262155];
    static int[] invFactorials = new int[262155];
    static int[] logs = new int[262155];
    static int[] cnt2 = new int[262155];
    static int[][] dp = new int[262155][31];
    static boolean[][] visited = new boolean[262155][31];
    static List<int[]> trace = new ArrayList<>();

    static int getInputInt(BufferedReader br) throws IOException {
        int x = 0;
        boolean neg = false;
        int c;
        while (true) {
            c = br.read();
            if (c == -1) break;
            if (c == '-') {
                neg = true;
            } else if (Character.isDigit(c)) {
                x = c - '0';
                break;
            }
        }
        while (true) {
            c = br.read();
            if (c == -1 || !Character.isDigit(c)) break;
            x = x * 10 + (c - '0');
        }
        return neg ? -x : x;
    }

    static long getInputLong(BufferedReader br) throws IOException {
        long x = 0;
        boolean neg = false;
        int c;
        while (true) {
            c = br.read();
            if (c == -1) break;
            if (c == '-') {
                neg = true;
            } else if (Character.isDigit(c)) {
                x = c - '0';
                break;
            }
        }
        while (true) {
            c = br.read();
            if (c == -1 || !Character.isDigit(c)) break;
            x = x * 10 + (c - '0');
        }
        return neg ? -x : x;
    }

    static int countDiv2(int x) {
        int cnt = 0;
        while (x != 0 && (x & 1) == 0) {
            cnt++;
            x >>= 1;
        }
        return cnt;
    }

    static int fast_pow(int base, long exp) {
        long res = 1;
        long b = base;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return (int) res;
    }

    static int choose(int n, int m) {
        return (int) (((long) factorials[n] * invFactorials[m] % mod) * invFactorials[n - m] % mod);
    }

    static int recurse(int n, int k) {
        if (n == 0) return 1;
        if (k == 0) return 0;
        if (dp[n][k] != -1) return dp[n][k];
        int res = 0;
        int limit = 1 << logs[n];
        for (int i = n; i >= limit; i -= 2) {
            res = (res + (int) (((long) choose(n, i) * recurse(n - i, k - 1)) % mod) * k) % mod;
        }
        return dp[n][k] = res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = getInputInt(br);
        k = getInputInt(br);
        mod = getInputLong(br);

        factorials[0] = 1;
        for (int i = 1; i <= 262150; i++) {
            factorials[i] = (int) ((long) factorials[i - 1] * i % mod);
            logs[i] = logs[i >> 1] + 1;
            cnt2[i] = cnt2[i - 1] + countDiv2(i);
        }

        invFactorials[262150] = fast_pow(factorials[262150], mod - 2);
        for (int i = 262149; i > 0; i--) {
            invFactorials[i] = (int) ((long) invFactorials[i + 1] * (i + 1) % mod);
        }
        invFactorials[0] = invFactorials[1];

        if ((n & 1) == 1) {
            System.out.println(fast_pow(k, n));
        } else {
            int cnt = 0;
            for (int i = 0; i < 62; i++) {
                if (((long) n & (1L << i)) != 0) cnt++;
            }
            int ans = fast_pow(k, n);
            int res = ((ans - recurse(n, k)) % (int) mod + (int) mod) % (int) mod;
            System.out.println(res);
        }
    }
}
